static void scalar(JSValue v){int tag=JS_VALUE_GET_NORM_TAG(v);uint64_t bits;if(tag==JS_TAG_FLOAT64){double d=JS_VALUE_GET_FLOAT64(v);memcpy(&bits,&d,8);}else bits=(uint64_t)(uint32_t)JS_VALUE_GET_INT(v);fwrite(&tag,4,1,stdout);fwrite(&bits,8,1,stdout);}
static void result(JSContext *ctx,JSValue v,int object){if(object&&JS_IsObject(v)){JSValue x=JS_GetProperty(ctx,v,JS_ATOM_value),d=JS_GetProperty(ctx,v,JS_ATOM_done);scalar(x);scalar(d);JS_FreeValue(ctx,x);JS_FreeValue(ctx,d);}else scalar(v);}
static void promise(JSContext *ctx,JSValue p,int object){assert(!JS_IsException(p));int state=JS_PromiseState(ctx,p);fwrite(&state,4,1,stdout);JSValue r=JS_PromiseResult(ctx,p);result(ctx,r,object);JS_FreeValue(ctx,r);}
