  for(int await_value=0;await_value<2;await_value++){len=0;code[len++]=OP_initial_yield;push(code,&len,i-17);if(await_value){code[len++]=OP_await;code[len++]=OP_drop;push(code,&len,i+19);}code[len++]=OP_yield;code[len++]=OP_drop;code[len++]=OP_drop;push(code,&len,i+29);code[len++]=OP_return_async;f=function(ctx,JS_FUNC_ASYNC_GENERATOR,code,len);JSValue g=JS_Call(ctx,f,JS_UNDEFINED,0,NULL);assert(!JS_IsException(g));for(int k=0;k<3;k++){JSValue p=js_async_generator_next(ctx,g,1,&arg,GEN_MAGIC_NEXT);promise(ctx,p,TRUE);drain(rt);promise(ctx,p,TRUE);JS_FreeValue(ctx,p);}JS_FreeValue(ctx,g);JS_FreeValue(ctx,f);}
